head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.gSndlocTp = $c.frame.path("../frame_head").gSndlocTpCd;
scwin.gAcptNo = $c.frame.path("../frame_head").scwin.gAcptNo;
scwin.gDisclsAcptTpCd = $c.frame.path("../frame_head").scwin.gDisclsAcptTpCd; // 공시접수유형
scwin.gProcsStatCd = $c.frame.path("../frame_head").scwin.gProcsStatCd;
scwin.gDepCd = js_dep_cd;
scwin.gDutyGrp = js_gduty;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gEmpNo = js_emp_no; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.gProcYn;
scwin.gPublYn;
scwin.gExtrcYn;
scwin.gApprovYn;
scwin.gListFormYn;
scwin.gDisclsStatCd;
scwin.gDisclsStatCd_00 = '00'; //미처리
scwin.gDisclsStatCd_10 = '10'; //검토
scwin.gDisclsStatCd_20 = '20'; //보류
scwin.gDisclsStatCd_30 = '30'; //승인
scwin.gDisclsStatCd_40 = '40'; //유보
scwin.gDisclsStatCd_50 = '50'; //기처리
scwin.gDisclsStatCd_99 = '99'; //삭제

//var gAcptApplTpCd="";

scwin.vIsurCd;
scwin.vComAbbrv;
scwin.vSecuGrpId;
scwin.vMainFormCd;
scwin.vMktTpCd;
scwin.vListBzTpCd;
scwin.vPageMoveYn = 'Y';
scwin.gListProcsLogYn = 'Y';
scwin.vUrl;
scwin.vWinTitle;
scwin.vPROCS_STAT_CD;
scwin.gTrdHaltMsg = $c.frame.path("../frame_head").scwin.gTrdHaltMsg;
scwin.vScrenID = 'ULDSTF10105.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


// 상장문서 처리절차가져오기
scwin.fn_ListingProcsFlag = function() {
    var url = "/Viewer.do?method=getListingProcObjYn&inputMessageId=VIEWER_LISTING_PROCOBJYN_OUT" + "&ACPT_NO=" + scwin.gAcptNo;
    dts_ListingProcsFlag.DataID = encodeURI(url);
    dts_ListingProcsFlag.reset();
};
scwin.fn_SetHeader = function() {
    // 가우스헤더 셋팅
    dts_AcptProcs.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LISTING_PROC_IN";
    dts_AcptProcs.reset();
};


// 로그인 사용자정보로 공시처리가능여부 체크
// 로직은 ULDSTF10008.gfm파일 참조.
scwin.fn_getProcButtonYN = function() {
    var url = "/Viewer.do?method=getProcBtnShowYn" + "&inputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&outputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&ACPT_NO=" + scwin.gAcptNo + "&DUTY_GRP_TP=" + scwin.gDutyGrp + "&DEP_CD=" + scwin.gDepCd;
    dts_btnshow.DataID = encodeURI(url);
    dts_btnshow.reset();
};


// 처리버튼 생성여부
scwin.fn_showProcButton = function(pDutyProcYn, pGrnlProcYn, pCloseYn) {
    //alert(gDutyYn+","+pDutyProcYn+","+pGrnlProcYn+","+pCloseYn);
    scwin.fn_getProcsSate(scwin.gAcptNo);
    if (scwin.gAcptNo != '') {
        // 가져온접수번호가 있으면 처리함.
        if (scwin.gApprovYn == 'Y') {
            //처리절차가 있을 경우 

            $c.stf.showObj(panel_1, false);
            if ((scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') && pDutyProcYn == 'Y') {
                $c.stf.showObj(panel_2, true);
                if (scwin.gProcsStatCd == '00') {
                    //미처리
                    img_approval.src = "../img/btn_approval_d.gif";
                    img_approval.setDisabled(true);
                } else if (scwin.gProcsStatCd == '10') {
                    //접수
                    img_acpt.src = "../img/btn_Acpt_d.gif";
                    img_acpt.setDisabled(true);
                } else {
                    img_acpt.src = "../img/btn_Acpt_d.gif";
                    img_acpt.setDisabled(true);
                    img_approval.src = "../img/btn_approval_d.gif";
                    img_approval.setDisabled(true);
                    img_res.src = "../img/btn_reserve_d.gif";
                    img_res.setDisabled(true);
                }
            } else {
                // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                if (scwin.gJobTitle == '09' || scwin.gJobTitle == '40') {
                    // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.
                    $c.stf.showObj(panel_2, true);
                    if (scwin.gProcsStatCd == '00') {
                        //미처리
                        img_approval.src = "../img/btn_approval_d.gif";
                        img_approval.setDisabled(true);
                    } else if (scwin.gProcsStatCd == '10') {
                        //검토
                        img_acpt.src = "../img/btn_Acpt_d.gif";
                        img_acpt.setDisabled(true);
                    } else {
                        img_acpt.src = "../img/btn_Acpt_d.gif";
                        img_acpt.setDisabled(true);
                        img_approval.src = "../img/btn_approval_d.gif";
                        img_approval.setDisabled(true);
                        img_res.src = "../img/btn_reserve_d.gif";
                        img_res.setDisabled(true);
                    }
                } else {
                    // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                    if (pGrnlProcYn == 'Y') {
                        $c.stf.showObj(panel_2, true);
                        if (scwin.gProcsStatCd == '00') {
                            //미처리
                            img_approval.src = "../img/btn_approval_d.gif";
                            img_approval.setDisabled(true);
                        } else if (scwin.gProcsStatCd == '10') {
                            //검토
                            img_acpt.src = "../img/btn_Acpt_d.gif";
                            img_acpt.setDisabled(true);
                            //유가 - 일반사용자(팀원)도 승인권한을 준다. 2020.09.04
                            //img_approval.src = "../img/btn_approval_d.gif";
                            //img_approval.disabled = true;

                        } else {
                            img_acpt.src = "../img/btn_Acpt_d.gif";
                            img_acpt.setDisabled(true);
                            img_approval.src = "../img/btn_approval_d.gif";
                            img_approval.setDisabled(true);
                            img_res.src = "../img/btn_reserve_d.gif";
                            img_res.setDisabled(true);
                        }
                    } else {
                        $c.stf.showObj(panel_2, false);
                    }
                }
            }
        } else {
            $c.stf.showObj(panel_2, false);

            // 로그한 사용자가 당번이면서 접수문서가 당번그룹에 해당할 경우
            if ((scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') && pDutyProcYn == 'Y') {
                $c.stf.showObj(panel_1, true);
            } else {
                // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                if (scwin.gJobTitle == '09' || scwin.gJobTitle == '40') {
                    // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.
                    $c.stf.showObj(panel_1, true);
                } else {
                    // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                    if (pGrnlProcYn == 'Y') {
                        $c.stf.showObj(panel_1, true);
                    } else {
                        $c.stf.showObj(panel_1, false);
                        if (js_belngdepcd == '3300' || js_belngdepcd == '3E00') {
                            if (scwin.vMainFormCd == '72088' || scwin.vMainFormCd == '72089' || scwin.vMainFormCd == '72090') {
                                $c.stf.showObj(panel_1, true);
                            }
                        }
                    }
                }
            }
        }
    }
};



//유가공시부 접수처리
scwin.fn_DsclAcpt = function() {
    dts_AcptList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLPROC_IN";
    dts_AcptList.reset();
    var vTrnsmtp = '1'; //1=전송(일반) ,  2=비전송(HTS제외 전송) , 3=비공개(웹)

    dts_AcptList.insertRow();
    dts_AcptList.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptList.setCellData(1, "TRNSM_TP_CD", vTrnsmtp);
    dts_AcptList.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptList.setCellData(1, "NXTDD_TDD_TP", "2");
    dts_AcptList.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    var vAnswer = confirm('검토처리 하시겠습니까?');
    if (vAnswer == true) {
        if (scwin.fn_checkProcsSate(scwin.gAcptNo) == false) {
            scwin.fn_CloseParentReload();
            return false;
        } else {
            trs_AcptList.Action = "/DisclosureStudy.do?method=processDisclosureStudy&inputMessageId=DSCLPROC_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
            trs_AcptList.KeyName = "toinb_dataid4";
            trs_AcptList.KeyValue = "JSP(I:pInput=dts_AcptList)";
            trs_AcptList.Post();
        }
    }
};





//mktTP : 1:유가, 2:코스닥&코넥스
// 검토처리하기
scwin.fn_DsclStudy = function(mktTP) {
    // 전송구분 셋팅

    if (scwin.gAcptNo == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    /*
    if (gListFormYn == 'Y') {
    	gDisclsStatCd = gDisclsStatCd_30;
    	gListProcsLogYn = 'Y';
    } else {
    	if (gPublYn == 'N') {
    		gDisclsStatCd = gDisclsStatCd_30;
    	} else {
    		gDisclsStatCd = gDisclsStatCd_00;
    	}
    }

    if (gListFormYn == 'N' && gPublYn == 'Y') {
    	gAcptApplTpCd = 'D'; //접수신청구분코드 (상장신청에서 공시접수로 변경한다. )
    }
    */

    //유가가 아닌 경우에만 처리여부를 확인한다.
    //유가는 검토, 승인 단계가 있지만 코&넥은 없음.  00이 아닌경우 튕겨 내도록했기에 검토,승인이 없는 코&넥만 적용.
    if (mktTP == 2) {
        if (scwin.fn_checkProcsSateKOSDAQ(scwin.gAcptNo) == false) {
            scwin.fn_CloseParentReload();
            return false;
        }
    }
    scwin.gDisclsStatCd = scwin.gDisclsStatCd_30; //신고서식 모두 공시검토에서 처리하여 '30'으로 셋팅

    var vAnswer;
    if (scwin.gApprovYn == 'Y') {
        vAnswer = confirm('승인처리 하시겠습니까?');
    } else {
        vAnswer = confirm('접수처리 하시겠습니까?');
    }
    if (vAnswer == true) {
        scwin.fn_setParam();
        var vBzProcsNo = "";
        if (scwin.gListProcsLogYn == 'Y') {
            vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
            if (vBzProcsNo.length != 14) {
                $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
                return;
            }
        }

        /*
        alert("[vIsurCd(회사코드)]:"+vIsurCd+
        		"\n[gListFormYn(상장신청서 여부)]:"+gListFormYn+
        		"\n[gPublYn(공시처리여부)]:"+gProcYn+
        		"\n[gPublYn(배포여부)]:"+gPublYn+
        		"\n[gPublYn(추출여부)]:"+gExtrcYn+
        		"\n[gAcptApplTpCd(접수신청구분)]:"+gAcptApplTpCd
        		);
        */ //
        scwin.fn_SetHeader();
        var vTrnsmtp = '1'; //1=전송(일반) ,  2=비전송(HTS제외 전송) , 3=비공개(웹)
        //var vTrnsmtp = getObjectValue(rdo_trnsmtp);
        //alert(vTrnsmtp +"="+gAcptNo);

        dts_AcptProcs.insertRow();
        dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
        dts_AcptProcs.setCellData(1, "TRNSM_TP_CD", vTrnsmtp);
        dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
        dts_AcptProcs.setCellData(1, "DISCLS_PROCS_STAT_CD", scwin.gDisclsStatCd);
        //dts_AcptProcs.NameValue(1,"ACPT_APPL_TP_CD") = gAcptApplTpCd;
        dts_AcptProcs.setCellData(1, "LIST_PROCS_LOG_YN", scwin.gListProcsLogYn);
        dts_AcptProcs.setCellData(1, "DISCLS_ACPT_TP_CD", scwin.gDisclsAcptTpCd);
        dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
        if (dts_AcptProcs.getCellData(1, "ACPT_NO") == '') {
            $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
            return false;
        }

        //alert('[dts_AcptProcs]'+dts_AcptProcs.Text);
        //alert('/vBzProcsNo/'+vBzProcsNo+'/gAcptNo/'+gAcptNo+'/vMainFormCd/'+vMainFormCd);

        if (scwin.fn_checkProcsSate(scwin.gAcptNo) == false) {
            scwin.fn_CloseParentReload();
            return false;
        } else {
            trs_AcptProcs.Action = $c.lc.fn_encodeNSession("/DisclosureStudy.do?method=processListingStudy&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo);
            trs_AcptProcs.KeyName = "toinb_dataid4";
            trs_AcptProcs.KeyValue = "JSP(I:pInput=dts_AcptProcs)";
            trs_AcptProcs.Parameters = "BZ_PROCS_NO=" + vBzProcsNo + ",ACPT_NO=" + scwin.gAcptNo + ",FORM_CD=" + scwin.vMainFormCd + ",ISUR_CD=" + scwin.vIsurCd + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",LD_MKT_TP_CD=" + scwin.vMktTpCd;
            trs_AcptProcs.Post();
        }
    }
};
scwin.vPROCS_STAT_NM = '';
scwin.vPROCS_DDTM = '';
scwin.vBLOCK_YN = '';
// 처리상태 조회하기
scwin.fn_getProcsSate = function(gAcptNo) {
    var url = "/Viewer.do?method=getDsclProcsStat" + "&inputMessageId=VIEWER_OUT" + "&outputMessageId=VIEWER_OUT" + "&ACPT_NO=" + scwin.gAcptNo;
    dts_procs_stat.DataID = encodeURI(url);
    dts_procs_stat.reset();
    scwin.vPROCS_STAT_CD = dts_procs_stat.getCellData(1, "PROCS_STAT_CD");
    scwin.vPROCS_STAT_NM = dts_procs_stat.getCellData(1, "PROCS_STAT_NM");
    scwin.vPROCS_DDTM = dts_procs_stat.getCellData(1, "PROCS_DDTM");
    scwin.vBLOCK_YN = dts_procs_stat.getCellData(1, "BLOCK_YN");
};



// 처리상태 조회하기
scwin.fn_checkProcsSate = function(gAcptNo) {
    scwin.fn_getProcsSate(scwin.gAcptNo);
    if (scwin.vBLOCK_YN == 'Y') {
        $c.win.alert("(경고) 동사 주권의 매매거래가 정지되지 않았음을 알려드립니다. 거래시간 중 '매매거래정지 안내' 및 '관련공시' 배포는 매매거래가 정지된 이후 처리되어야 합니다. 거래정지 여부를 확인하신 후에 처리하시기 바랍니다.");
        return false;
    }
    if (scwin.gProcsStatCd != scwin.vPROCS_STAT_CD) {
        $c.win.alert("본 공시가 " + scwin.vPROCS_DDTM + "에  이미 [" + scwin.vPROCS_STAT_NM + "] 처리가 되었습니다.");
        //fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};



// 처리상태 조회하기
scwin.fn_checkProcsSateKOSDAQ = function(gAcptNo) {
    scwin.fn_getProcsSate(scwin.gAcptNo);
    if (scwin.vBLOCK_YN == 'Y') {
        $c.win.alert(scwin.gTrdHaltMsg);
        return false;
    }
    if (scwin.vPROCS_STAT_CD != '00') {
        $c.win.alert("본 공시가 " + scwin.vPROCS_DDTM + "에  이미 [" + scwin.vPROCS_STAT_NM + "] 처리가 되었습니다.");
        //fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};



//기업인수목적회사 구분 2010.05.30 화면 이동을 위해
scwin.fn_spacYN = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LISTING_SPAC_YN" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.isuinst.spac.condition" + "&{P}param01=" + scwin.vIsurCd + // 회사코드
        "&{P}param02=" + scwin.vMktTpCd; // 시장구분

    dts_spacYN.DataID = encodeURI(url);
    dts_spacYN.Reset();
};
scwin.fn_setParam = function() {
    scwin.fn_spacYN();
    //상장서식여부로 바꾸자
    if (scwin.vMainFormCd == '68001' || scwin.vMainFormCd == '68003' ||
        scwin.vMainFormCd == '68006' || scwin.vMainFormCd == '68008' ||
        scwin.vMainFormCd == '70932' || scwin.vMainFormCd == '70934' ||
        scwin.vMainFormCd == '33032') {
        if (dts_spacYN.getCellData(1, "SPAC_YN") == 'Y') {
            scwin.vUrl = "/lstproc/ULDSTF05255.gfm";
        } else {
            scwin.vUrl = "/lstproc/ULDSTF05200.gfm";
        }
        scwin.vWinTitle = "신주,추가상장";
        //vListBzTpCd = LIST_BZ_TP_CD_130; //120=신주상장, 130=추가상장 (추가상장, 신주상장하고 구분해야됨.)
        scwin.gListProcsLogYn = 'N';
    } else if (scwin.vMainFormCd == '68004' ||
        scwin.vMainFormCd == '68007' ||
        scwin.vMainFormCd == '70933' ||
        scwin.vMainFormCd == '33033') {
        if (dts_spacYN.getCellData(1, "SPAC_YN") == 'Y') {
            scwin.vUrl = "/lstproc/ULDSTF05256.gfm";
        } else {
            scwin.vUrl = "/lstproc/ULDSTF05201.gfm";
        }
        scwin.vWinTitle = "변경상장";
        //vListBzTpCd = LIST_BZ_TP_CD_141;
        scwin.gListProcsLogYn = 'N';
    } else if (scwin.vMainFormCd == '68901' || scwin.vMainFormCd == '70935') {
        scwin.vUrl = "/lstproc/ULDSTF05700.gfm";
        scwin.vWinTitle = "신주인수권증권 신주상장";
        scwin.vListBzTpCd = LIST_BZ_TP_CD_121;
    } else if (scwin.vMainFormCd == '68902' || scwin.vMainFormCd == '70936') {
        scwin.vUrl = "/lstproc/ULDSTF05701.gfm";
        scwin.vWinTitle = "신주인수권증권 변경상장";
        scwin.vListBzTpCd = LIST_BZ_TP_CD_144;
    } else if (scwin.vMainFormCd == '68009' || scwin.vMainFormCd == '70937') {
        scwin.vUrl = "/lstproc/ULDSTF05800.gfm";
        scwin.vWinTitle = "신주인수권증서 신주상장";
        scwin.vListBzTpCd = LIST_BZ_TP_CD_122;
    } else if (scwin.vMainFormCd == '68904') {
