scwin.fn_MoveBizProcPage = async function() {
    var url = "&" + scwin.vIsurCd;
    url += "&" + scwin.gAcptNo;
    url += "&" + scwin.vSecuGrpId;
    url += "&" + scwin.vMktTpCd;
    url += "&" + scwin.vComAbbrv;
    if ($c.frame.path("/top") != undefined) {
        $c.frame.path("/top").WinOpen("STF05200", scwin.vUrl + "?" + frame.FrameID + url, scwin.vWinTitle, 1275, 785);
    } else {
        await $c.frame.CreateFrame("STF05200", scwin.vUrl, scwin.vWinTitle, 10, 10, 1275, 785, "window", 0, 0, true);
    }
};



