scwin.fn_CloseParentReload = function() {
    // 화면닫기
    $c.frame.path("../").fn_CloseWin();
    $c.frame.path("../").fn_PvdSearch();
};
scwin.fn_GetParentProvider = function() {
    var url = $c.frame.path("../").srcUrl;
    var arr = url.split("?");
    //alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../../" + arr[1]) : undefined);
};


