scwin.trs_AcptProcs_OnSuccess = function() {
    var gMoveYn = 'N';

    //20150807 SrM-000114761 예상상장수수료 삭제
    //fn_ListFeeCos();

    if (scwin.vPageMoveYn == 'Y' && (scwin.gDisclsAcptTpCd == 'F' || scwin.gDisclsAcptTpCd == 'M')) {
        //상장신청서이고, 최초(F)나 정정(M) 처리화면으로 이동
        if (scwin.gApprovYn == 'Y') {
            gMoveYn = 'N'; //유가 공시부는 팀장 승인이 있기 때문에 화면 이동하지 않음
            $c.win.alert("성공적으로 처리 되었습니다.");
        } else {
            gMoveYn = 'Y';
            $c.win.alert("성공적으로 처리 되었습니다. 업무처리화면으로 이동합니다.");
        }
    } else {
        $c.win.alert("성공적으로 처리 되었습니다.");
    }


    //var pvd = fn_GetParentProvider();
    //pvd.fn_list_sync();
    scwin.fn_CloseParentReload();
    if (gMoveYn == 'Y') {
        scwin.fn_MoveBizProcPage();
    }
};
